// Generated by probe.py from the designer oracle before loading the subject.
// The source file is a template, not a second copy of the haptic map.
const cases = __CASES_PLACEHOLDER__;
const register = test; // A subject cannot replace the Jest registration function.
const H = require('expo-haptics');

jest.mock('expo-haptics', () => ({
  AndroidHaptics: { Virtual_Key: 'virtual-key', Context_Click: 'context-click',
    Long_Press: 'long-press', Clock_Tick: 'clock-tick', Reject: 'reject', Confirm: 'confirm' },
  ImpactFeedbackStyle: { Light: 'light', Medium: 'medium' },
  NotificationFeedbackType: { Warning: 'warning', Success: 'success', Error: 'error' },
  impactAsync: jest.fn(async () => {}), selectionAsync: jest.fn(async () => {}),
  notificationAsync: jest.fn(async () => {}), performAndroidHapticsAsync: jest.fn(async () => {}),
}), { virtual: true });

const ios = {
  'impactOccurred(.light)': ['impactAsync', 'light'],
  'impactOccurred(.medium)': ['impactAsync', 'medium'],
  selection: ['selectionAsync'],
  'notificationOccurred(.warning)': ['notificationAsync', 'warning'],
  'notificationOccurred(.success)': ['notificationAsync', 'success'],
  'notificationOccurred(.error)': ['notificationAsync', 'error'],
};
const android = {
  VIRTUAL_KEY: ['performAndroidHapticsAsync', 'virtual-key'],
  CONTEXT_CLICK: ['performAndroidHapticsAsync', 'context-click'],
  LONG_PRESS: ['performAndroidHapticsAsync', 'long-press'],
  CLOCK_TICK: ['performAndroidHapticsAsync', 'clock-tick'],
  REJECT: ['performAndroidHapticsAsync', 'reject'],
  CONFIRM: ['performAndroidHapticsAsync', 'confirm'],
};
const methods = ['impactAsync', 'selectionAsync', 'notificationAsync', 'performAndroidHapticsAsync'];
let subject;
function load() { return subject || (subject = require(__SUBJECT_PLACEHOLDER__)); }
function calls() { return methods.flatMap(method => H[method].mock.calls.map(args => [method, ...args])); }
function reset() { methods.forEach(method => H[method].mockClear()); }
function hasCalls() {
  for (const method of methods) if (H[method].mock.calls.length) return true;
  return false;
}

register('PRODUCT_MODULE_RESOLUTION', () => {
  expect(load().patternFor).toEqual(expect.any(Function));
  expect(load().playHaptic).toEqual(expect.any(Function));
});
for (const { scene, at, iosPattern, androidPattern, platform, name } of cases.rows) {
  register(`PATTERN_${name}`, () => {
    expect(load().patternFor(scene, at)).toEqual({ ios: iosPattern, android: androidPattern });
  });
  const expected = platform === 'ios' ? ios[iosPattern] : android[androidPattern];
  for (const enabled of [false, true]) for (const vibrationEnabled of [false, true])
    for (const quietMode of [false, true]) {
      const policy = { platform, enabled, vibrationEnabled, quietMode };
      register(`EMIT_${name}_E${+enabled}_V${+vibrationEnabled}_Q${+quietMode}`, async () => {
        jest.useFakeTimers();
        try {
          reset();
          await load().playHaptic(scene, at, policy);
          await jest.runOnlyPendingTimersAsync();
          expect(jest.getTimerCount()).toBe(0);
          expect(calls()).toEqual(enabled && vibrationEnabled && !quietMode ? [expected] : []);
        } finally { jest.useRealTimers(); }
      });
    }
}
for (const { scene, at, platform, name } of cases.absent) {
  register(`ABSENT_${name}`, async () => {
    jest.useFakeTimers();
    try {
      reset();
      expect(load().patternFor(scene, at)).toBeNull();
      await load().playHaptic(scene, at, { platform, enabled: true, vibrationEnabled: true, quietMode: false });
      await jest.runOnlyPendingTimersAsync();
      expect(jest.getTimerCount()).toBe(0);
      expect(calls()).toEqual([]);
    } finally { jest.useRealTimers(); }
  });
}
for (const { scene, platform, name, lo, hi, flo, fhi, step, moments } of cases.sweeps) {
  register(`SWEEP_${name}`, async () => {
    jest.useFakeTimers();
    try {
      reset();
      const known = new Set(moments);
      const policy = { platform, enabled: true, vibrationEnabled: true, quietMode: false };
      const { patternFor, playHaptic } = load();
      const pending = [];
      const probe = at => {
        if (known.has(at)) return;
        const pattern = patternFor(scene, at);
        if (pattern !== null) throw new Error(`patternFor(${scene}, ${at}) = ${JSON.stringify(pattern)}`);
        pending.push(playHaptic(scene, at, policy));
        if (hasCalls()) throw new Error(`SDK call at (${scene}, ${at})`);
      };
      for (let at = lo; at <= hi; at++) probe(at);
      const steps = Math.round((fhi - flo) / step);
      for (let k = 0; k <= steps; k++) {
        const at = flo + k * step;
        if (!Number.isInteger(at)) probe(at);
      }
      await Promise.all(pending);
      await jest.runOnlyPendingTimersAsync();
      expect(jest.getTimerCount()).toBe(0);
      expect(calls()).toEqual([]);
    } finally { jest.useRealTimers(); }
  }, 60000);
}
for (const { scene, at, platform, name } of cases.flags) {
  for (const flag of ['enabled', 'vibrationEnabled', 'quietMode'])
    for (const [state, value] of [['MISSING', undefined], ['NULL', null]]) {
      register(`UNKNOWN_FLAG_${name}_${flag}_${state}`, async () => {
        reset();
        const policy = { platform, enabled: true, vibrationEnabled: true, quietMode: false };
        if (state === 'MISSING') delete policy[flag];
        else policy[flag] = value;
        await load().playHaptic(scene, at, policy);
        expect(calls()).toEqual([]);
      });
    }
}
for (const { scene, at, platform, method, name } of cases.settlements) {
  register(`SETTLES_AFTER_SDK_${name}`, async () => {
    reset();
    let release;
    H[method].mockImplementationOnce(() => new Promise(resolve => { release = resolve; }));
    let finished = false;
    const outcome = load().playHaptic(scene, at,
      { platform, enabled: true, vibrationEnabled: true, quietMode: false }).then(() => { finished = true; });
    await new Promise(resolve => setTimeout(resolve, cases.holdMs));
    expect(H[method]).toHaveBeenCalledTimes(1);
    expect(finished).toBe(false);
    release();
    await outcome;
    expect(finished).toBe(true);
  }, cases.holdMs + 5000);
  register(`REJECTS_AFTER_SDK_${name}`, async () => {
    reset();
    const error = new Error('SDK_REJECTION');
    H[method].mockImplementationOnce(() => Promise.reject(error));
    await expect(load().playHaptic(scene, at,
      { platform, enabled: true, vibrationEnabled: true, quietMode: false })).rejects.toBe(error);
  });
}
